#!/bin/bash
# DLinear on PEMS04: input 96, horizons 12 24 48 96; settings of the official scripts, protocol of the official loaders.
# Generated by scripts/multivariate_forecasting/make_scripts.py: change the profile and generate again.
#   bash scripts/multivariate_forecasting/PEMS/DLinear_PEMS04.sh                                   seeds 2021 2022 2023
#   SEEDS="2021" EXTRA_ARGS="--no_use_gpu --num_workers 0" bash scripts/multivariate_forecasting/PEMS/DLinear_PEMS04.sh   one seed on the CPU
# Results: output/long_term_forecast/PEMS04.tsv (one row per run); checkpoints: temp/checkpoints/PEMS04/.
export CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES:-0}
cd "$(dirname "$0")/../../.."
root="$(python -m src.utils.paths root PEMS04.npz)/"
seeds=(${SEEDS:-2021 2022 2023})

# horizon 12: Time-Series-Library defaults (no script for this dataset)
for seed in "${seeds[@]}"; do
  python -u scripts/run.py \
    --is_training 1 \
    --model DLinear \
    --des PEMS04_12_DLinear \
    --seed "$seed" \
    --root_path "$root" \
    --data_path PEMS04.npz \
    --data PEMS \
    --model_id PEMS04_96_12 \
    --features M \
    --seq_len 96 \
    --label_len 48 \
    --pred_len 12 \
    --enc_in 307 \
    --dec_in 307 \
    --c_out 307 \
    --freq h \
    --drop_last \
    --test_batch_size 1 \
    --no_time_marks \
    $EXTRA_ARGS
done

